    "dj.faq1_q":          "I'm a complete beginner. Do I stand a chance?",
    "dj.faq1_preview":    "Yes — the course teaches from \"where to click\" to \"what should appear\".",
    "dj.faq1_a1":         "You'll learn to edit files, save, and refresh the browser.",
    "dj.faq1_a2":         "When something goes wrong, you'll have \"what to do\" (not just theory).",
    "dj.faq2_q":          "Why do I need to log in if it's free?",
    "dj.faq2_preview":    "To save progress, unlock downloads, use checklists and prepare review.",
    "dj.faq2_a":          "The Social content is free. Login turns it into a real journey: saved progress, downloads, checklists and preparation for manual review.",
    "dj.faq3_q":          "Is there video, community, or support?",
