    "svc2.kicker":               "Bespoke · Briefing-first · Built around your offer",
    "svc2.hero_title":           "Full site + brand — built with you, not for the crowd.",
    "svc2.hero_desc":            "A custom website and brand identity project led through a focused briefing process. Discovery call, written brief, fixed quote, your approval — then build. Not a template. Not instant. Built to carry your business.",
    "svc2.hero_book":            "Book a discovery call",
    "svc2.hero_whatsapp":        "WhatsApp",
    "svc2.hero_plans":           "See the process",
    "svc2.stat1_val":            "Bespoke",
    "svc2.stat1_label":          "Zero templates",
    "svc2.stat2_val":            "2-6 wks",
    "svc2.stat2_label":          "Typical timeline",
    "svc2.stat3_val":            "Quote",
    "svc2.stat3_label":          "Fixed, written, approved",
    "svc2.stat4_val":            "1-to-1",
    "svc2.stat4_label":          "1-to-1 guidance",
    "svc2.fit_eyebrow":          "Fit check",
    "svc2.fit_title":            "Who this is for — and who it isn't.",
    "svc2.fit_yes_title":        "This is for you if",
    "svc2.fit_yes1":             "<strong>You're launching a premium product or service</strong> and need a site + brand that matches the standard you sell at.",
    "svc2.fit_yes2":             "<strong>You need real positioning.</strong> Not a logo and three colours — a full brand system aligned with how you sell.",
    "svc2.fit_yes3":             "<strong>You want a project architect, not a relay race</strong> — strategy, copy, design, code and brand stay aligned under one VOLYNX direction.",
    "svc2.fit_yes4":             "<strong>You're ready for a process</strong> — brief, quote, approval, build. Not a 24h hack.",
    "svc2.fit_no_title":         "This isn't for you if",
    "svc2.fit_no1":              "<strong>You need a single landing fast.</strong> The <a href=\"/products/saas-landing-system/\">SaaS Landing System</a> ships instantly and autonomously.",
    "svc2.fit_no2":              "<strong>You want to DIY.</strong> <a href=\"/builder/\">VOLYNX Builder</a> gives you the platform to build yourself, guided.",
    "svc2.fit_no3":              "<strong>You want 'just a website' without strategy.</strong> This is brand + positioning + build. If you only need build, a kit fits better.",
    "svc2.fit_no4":              "<strong>Budget below the starting tier.</strong> Project minimums apply — see scope packages below.",
    "svc2.process_eyebrow":      "How it runs",
    "svc2.process_title":        "Six steps. No guessing.",
    "svc2.process_desc":         "Every project follows the same spine. You know exactly what's happening, what's next, and what's pending on your side.",
    "svc2.step1_num":            "01",
    "svc2.step1_title":          "Discovery call",
    "svc2.step1_desc":           "30-45 min on Calendly. We cover your offer, audience, constraints, existing assets and the win condition.",
    "svc2.step2_num":            "02",
    "svc2.step2_title":          "Brief analysis",
    "svc2.step2_desc":           "The call becomes a written brief: what you're selling, to whom, what the site and brand need to accomplish.",
    "svc2.step3_num":            "03",
    "svc2.step3_title":          "Quote & timeline",
    "svc2.step3_desc":           "Fixed written quote, clear milestones, deposit terms. No hourly billing. No surprise extras.",
    "svc2.step4_num":            "04",
    "svc2.step4_title":          "Approval",
    "svc2.step4_desc":           "You sign off the scope and deposit. Work doesn't start before approval. Nothing assumed.",
    "svc2.step5_num":            "05",
    "svc2.step5_title":          "Build & iteration",
    "svc2.step5_desc":           "Brand, design, copy and code in parallel. Scheduled review checkpoints. Revisions inside scope.",
    "svc2.step6_num":            "06",
    "svc2.step6_title":          "Delivery & handoff",
    "svc2.step6_desc":           "Launch, training, source-file transfer and optional maintenance plan. Full ownership is yours.",
    "svc2.plans_eyebrow":        "Scope packages",
    "svc2.plans_title":          "Three starting scopes. All priced per project.",
    "svc2.plans_desc":           "Starting prices below. Final quote is written after your brief — fixed, in the discovery call follow-up. No checkout here: projects move after a call.",
    "svc2.plan1_delivery":       "From £1,500 · 2 weeks",
    "svc2.plan1_title":          "Essential",
    "svc2.plan1_desc":           "One premium landing page built from your brief, with a tight brand kit. For focused launches where a single page carries the pitch.",
