    /* === PRIVACY === */
    "priv.title": "Privacy Policy",
    "priv.intro": "This policy explains how Volynx collects, uses, and protects your personal data when you use our website, tools, and digital products at <strong>volynx.world</strong>.",
    "priv.collect_title": "What we collect",
    "priv.collect_account": "<strong>Account data</strong> — name and email address when you create an account or sign in via Supabase Auth.",
    "priv.collect_payment": "<strong>Payment data</strong> — billing information processed securely by Stripe. Volynx never stores card numbers directly.",
    "priv.collect_usage": "<strong>Usage data</strong> — pages visited, tool interactions, and device/browser information for performance and analytics purposes.",
    "priv.collect_contact": "<strong>Contact data</strong> — messages and information you submit through our contact form (processed via Formspree).",
    "priv.collect_cookies": "<strong>Cookies</strong> — essential session cookies for authentication and optional analytics cookies.",
    "priv.why_title": "Why we collect it",
    "priv.why_account": "To create and manage your account and authenticate sessions",
    "priv.why_purchases": "To process purchases of digital products, icon packs, kits, and subscriptions",
    "priv.why_tools": "To deliver and improve our web tools (image processing, QR generator, converters)",
    "priv.why_support": "To respond to support and sales inquiries",
    "priv.why_legal": "To comply with legal and financial obligations",
    "priv.third_title": "Third-party services",
    "priv.third_supabase": "<strong>Supabase</strong> — authentication and database hosting (EU infrastructure)",
    "priv.third_stripe": "<strong>Stripe</strong> — payment processing. Subject to <a href=\"https://stripe.com/privacy\" target=\"_blank\" rel=\"noopener\">Stripe's Privacy Policy</a>.",
    "priv.third_formspree": "<strong>Formspree</strong> — contact form processing",
    "priv.third_cloudflare": "<strong>Cloudflare Pages</strong> — website hosting and CDN",
    "priv.cookies_title": "Cookies",
    "priv.cookies_desc": "We use essential cookies to keep you logged in and maintain session state. We may also use anonymous analytics cookies to understand usage patterns. You can disable non-essential cookies in your browser settings at any time.",
    "priv.retention_title": "Data retention",
    "priv.retention_desc": "Account data is retained while your account is active. You may request deletion at any time. Payment records are retained as required by applicable financial regulations.",
    "priv.rights_title": "Your rights",
    "priv.rights_access": "Request access to, correction, or deletion of your personal data",
    "priv.rights_consent": "Withdraw consent for marketing communications at any time",
    "priv.rights_complaint": "Lodge a complaint with your local data protection authority",
    "priv.contact_title": "Contact",
    "priv.contact_desc": "For privacy requests: <a href=\"mailto:privacy@volynx.world\">privacy@volynx.world</a>",
    "priv.updated": "Last updated: 2026-04-01",

    /* === TERMS === */
    "terms.title": "Terms of Service",
    "terms.intro": "These Terms govern your use of Volynx websites, tools, digital products, and services available at <strong>volynx.world</strong>. By using our platform, you agree to these terms.",
    "terms.products_title": "Products and licenses",
    "terms.products_license": "Digital products (icon packs, kits, landing systems, portfolio kits) are <strong>licensed, not sold</strong>. You receive a perpetual, non-exclusive, non-transferable license for personal or commercial use in your own projects.",
    "terms.products_redistribution": "Redistribution, resale, repackaging, or sublicensing of Volynx products as standalone assets is prohibited without written permission.",
    "terms.products_icons": "Icon packs and design systems may be used in unlimited client projects under a single license.",
    "terms.tools_title": "Web tools (Volynx Lab & Studio)",
    "terms.tools_free": "Free tools are provided as-is with usage limits. Studio (Pro) subscriptions remove limits and unlock advanced features.",
    "terms.tools_files": "You are responsible for the files you upload and process. Volynx does not store processed files beyond the active session.",
    "terms.tools_unlawful": "Tools may not be used for unlawful purposes or to process content that violates third-party rights.",
    "terms.accounts_title": "Accounts",
    "terms.accounts_security": "You are responsible for maintaining the security of your account credentials.",
    "terms.accounts_sharing": "Accounts found sharing access or circumventing subscription limits may be suspended without refund.",
    "terms.payments_title": "Payments and refunds",
    "terms.payments_digital": "<strong>Digital products</strong> (one-time purchases): due to the nature of digital goods, all sales are final once the product has been accessed or downloaded. If you experience a technical issue, contact us within 7 days.",
    "terms.payments_subs": "<strong>Subscriptions</strong>: billed monthly or annually via Stripe. You may cancel at any time; access continues until the end of the paid period. No partial refunds for unused time.",
    "terms.payments_services": "<strong>Services</strong> (Landing Express, Maintenance Plans, agency work): payment and refund terms are defined per engagement and stated in the project proposal or invoice.",
    "terms.liability_title": "Limitation of liability",
    "terms.liability_desc": "To the maximum extent permitted by applicable law, Volynx is not liable for indirect, incidental, special, or consequential damages arising from use of the platform, tools, or products — including loss of data, revenue, or business opportunity.",
    "terms.changes_title": "Changes to these terms",
    "terms.changes_desc": "We may update these terms as our products evolve. Material changes will be communicated via email or a notice on the site. Continued use after changes constitutes acceptance.",
    "terms.contact_title": "Contact",
    "terms.contact_desc": "Questions about these terms: <a href=\"mailto:contact@volynx.world\">contact@volynx.world</a>",
    "terms.updated": "Last updated: 2026-04-01",

