    "priv.contact_title": "Contato",
    "priv.contact_desc": "Para solicitações de privacidade: <a href=\"mailto:privacy@volynx.world\">privacy@volynx.world</a>",
    "priv.updated": "Última atualização: 2026-04-01",

    /* === TERMS === */
    "terms.title": "Termos de Serviço",
    "terms.intro": "Estes Termos regem o uso dos sites, ferramentas, produtos digitais e serviços da Volynx disponíveis em <strong>volynx.world</strong>. Ao usar nossa plataforma, você concorda com estes termos.",
    "terms.products_title": "Produtos e licenças",
    "terms.products_license": "Produtos digitais (pacotes de ícones, kits, sistemas de landing, kits de portfólio) são <strong>licenciados, não vendidos</strong>. Você recebe uma licença perpétua, não exclusiva e intransferível para uso pessoal ou comercial em seus próprios projetos.",
    "terms.products_redistribution": "Redistribuição, revenda, reembalagem ou sublicenciamento de produtos Volynx como ativos independentes é proibido sem permissão por escrito.",
    "terms.products_icons": "Pacotes de ícones e sistemas de design podem ser usados em projetos de clientes ilimitados sob uma única licença.",
    "terms.tools_title": "Ferramentas web (Volynx Lab & Studio)",
    "terms.tools_free": "Ferramentas gratuitas são fornecidas como estão, com limites de uso. Assinaturas Studio (Pro) removem limites e desbloqueiam recursos avançados.",
    "terms.tools_files": "Você é responsável pelos arquivos que envia e processa. A Volynx não armazena arquivos processados além da sessão ativa.",
    "terms.tools_unlawful": "As ferramentas não podem ser usadas para fins ilegais ou para processar conteúdo que viole direitos de terceiros.",
    "terms.accounts_title": "Contas",
    "terms.accounts_security": "Você é responsável por manter a segurança das credenciais da sua conta.",
    "terms.accounts_sharing": "Contas encontradas compartilhando acesso ou contornando limites de assinatura podem ser suspensas sem reembolso.",
    "terms.payments_title": "Pagamentos e reembolsos",
    "terms.payments_digital": "<strong>Produtos digitais</strong> (compras únicas): devido à natureza dos bens digitais, todas as vendas são finais após o produto ter sido acessado ou baixado. Se você tiver um problema técnico, entre em contato conosco dentro de 7 dias.",
    "terms.payments_subs": "<strong>Assinaturas</strong>: cobradas mensalmente ou anualmente via Stripe. Você pode cancelar a qualquer momento; o acesso continua até o final do período pago. Sem reembolsos parciais por tempo não utilizado.",
    "terms.payments_services": "<strong>Serviços</strong> (Landing Express, Planos de Manutenção, trabalho de agência): termos de pagamento e reembolso são definidos por engajamento e declarados na proposta do projeto ou fatura.",
    "terms.liability_title": "Limitação de responsabilidade",
    "terms.liability_desc": "Na extensão máxima permitida pela lei aplicável, a Volynx não é responsável por danos indiretos, incidentais, especiais ou consequenciais decorrentes do uso da plataforma, ferramentas ou produtos — incluindo perda de dados, receita ou oportunidade de negócio.",
    "terms.changes_title": "Alterações nestes termos",
    "terms.changes_desc": "Podemos atualizar estes termos conforme nossos produtos evoluem. Alterações materiais serão comunicadas por e-mail ou aviso no site. O uso continuado após as alterações constitui aceitação.",
    "terms.contact_title": "Contato",
    "terms.contact_desc": "Dúvidas sobre estes termos: <a href=\"mailto:contact@volynx.world\">contact@volynx.world</a>",
    "terms.updated": "Última atualização: 2026-04-01",

